import json
from pathlib import Path
from fractions import Fraction
R=Path(__file__).resolve().parents[3]
sub='9702-7.1'; k=lambda n:f'{sub}.{n}'
pack={'subtopic':sub,'spec':'9702','version':1,'note':'Subjects/9702 Physics/07 Waves/7.1 Progressive waves.md','outline':'A progressive wave transfers energy as neighbouring particles vibrate about equilibrium. Describe displacement, amplitude, phase difference, period, frequency, wavelength and speed precisely. A CRO time-base gives time per division; y-gain gives voltage per division. In one period a wave advances one wavelength, so $v=f\\lambda$. Intensity is power per area and is proportional to amplitude squared for waves of the same type in the same medium.','misconceptions':[],'worked':[],'items':[],'flashcards':[],'diagrams':[]}
mis=[(2,'m1','Amplitude is peak-to-peak displacement.','Amplitude is maximum displacement from equilibrium; peak-to-peak is twice it.','peak-to-peak = 2A','ER 9702 s23 P23 Q4'),(3,'m2','CRO trace height directly gives sound displacement.','Y-gain converts screen height to voltage; microphone calibration is needed to obtain sound displacement.','screen amplitude in V versus particle amplitude in m','ER 9702 s22 P13 Q23'),(4,'m3','One wavelength travels in one second.','One wavelength travels in one period, which is $1/f$.','one period versus one second','research'),(7,'m4','Intensity is proportional to amplitude.','At fixed medium and frequency, intensity is proportional to amplitude squared.','double amplitude gives four times intensity','ER 9702 w19 P13 Q25'),(6,'m5','The medium travels with the wave.','Particles oscillate about equilibrium while the disturbance transfers energy.','oscillation versus propagation','research')]
for n,i,s,r,c,src in mis: pack['misconceptions'].append(dict(id=i,kc=k(n),statement=s,refutation=r,contrast=c,source=src))
qa={
1:[('Describe','wave motion','Wave motion is propagation of a disturbance through a medium or space, transferring energy.'),('Describe','a rope wave','A pulse travels along the rope while each rope element vibrates about its equilibrium position.'),('Describe','a spring wave','A disturbance travels along the spring as its coils vibrate about equilibrium.'),('Describe','ripples in a tank','Ripples spread from the source while water particles oscillate about equilibrium.'),('Explain','why a floating marker does not follow a ripple across a tank','The marker oscillates around one place as wave energy travels across the tank.'),('Compare','motion of a ripple and a water particle','The ripple propagates across the surface; a particle vibrates about its equilibrium position.')],
2:[('Define','displacement','Displacement is the distance and direction of a particle from its equilibrium position.'),('Define','amplitude','Amplitude is the maximum displacement of a particle from its equilibrium position.'),('Define','period','Period is the time for one complete oscillation of a particle.'),('Define','frequency','Frequency is the number of complete oscillations per unit time.'),('Define','wavelength','Wavelength is the distance between two consecutive points in phase on a wave.'),('Describe','phase difference and wave speed','Phase difference is the fraction of a cycle separating oscillations, expressed as an angle; wave speed is the distance travelled by a wavefront per unit time.')],
3:[('State','what CRO time-base specifies','Time-base is the time represented by one horizontal division.'),('State','what CRO y-gain specifies','Y-gain is the voltage represented by one vertical division.'),('Explain','how to find frequency from a CRO trace','Count horizontal divisions for one complete cycle; multiply by time per division for period, then take its reciprocal.'),('Explain','how to find voltage amplitude from a CRO trace','Count vertical divisions from centre line to peak and multiply by voltage per division.'),('Explain','why CRO voltage amplitude need not be sound displacement amplitude','A microphone converts displacement or pressure to voltage; its calibration is required to infer particle displacement.'),('Describe','a full-cycle CRO measurement','Measure between matching points such as two adjacent peaks, not from peak to trough.')],
4:[('Show (that)','the wave equation','In one period $T$, a wave advances one wavelength $\\lambda$, so $v=\\lambda/T$. As $f=1/T$, $v=f\\lambda$.'),('State','distance advanced in one period','A progressive wave advances one wavelength in one period.'),('State','frequency in terms of period','$f=1/T$.'),('Explain','why $v=\\lambda/T$','Speed is distance per time; the wave travels one wavelength in one period.'),('Show (that)','speed in terms of frequency and wavelength','Use $v=\\lambda/T$ and $T=1/f$ to obtain $v=f\\lambda$.'),('Explain','the units in the wave equation','Frequency has unit Hz or $\\mathrm{s^{-1}}$ and wavelength has unit m, giving speed in $\\mathrm{m\\,s^{-1}}$.')],
5:[('State','the wave equation','$v=f\\lambda$.'),('Explain','how wavelength changes when frequency doubles at fixed speed','Wavelength halves because $\\lambda=v/f$.'),('Explain','how frequency changes when wavelength triples at fixed speed','Frequency becomes one third because $f=v/\\lambda$.'),('Calculate','frequency for a wave of speed 12 m s^-1 and wavelength 3 m','$f=v/\\lambda=4$ Hz.'),('Calculate','wavelength for speed 20 m s^-1 and frequency 5 Hz','$\\lambda=v/f=4$ m.'),('Explain','why a graph of frequency against reciprocal wavelength is straight at fixed speed','From $f=v/\\lambda$, frequency is proportional to reciprocal wavelength, with gradient $v$.')],
6:[('State','what a progressive wave transfers','A progressive wave transfers energy.'),('Explain','how energy moves along a rope wave','A driven section transfers energy to adjacent sections, which vibrate about equilibrium.'),('Explain','why a ripple can transport energy without carrying water across the tank','Water particles oscillate locally while the disturbance passes onward.'),('Describe','particle motion as a wave passes','A particle oscillates about equilibrium as energy progresses through the wave.'),('Compare','energy motion with medium motion','Energy propagates with the wave; medium particles vibrate locally.'),('Explain','why a floating cork can bob while a ripple travels away','The cork follows local oscillation while the progressive disturbance carries energy outward.')],
7:[('Define','wave intensity','Intensity is the power transferred per unit area normal to the direction of wave travel.'),('State','intensity in terms of power and area','$I=P/A$.'),('State','intensity dependence on amplitude','For comparable progressive waves, $I\\propto a^2$.'),('Calculate','intensity when 12 W crosses 3 m^2','$I=P/A=4$ W m^-2.'),('Explain','effect of doubling amplitude at fixed medium and frequency','Intensity becomes four times as large because it is proportional to amplitude squared.'),('Explain','effect of halving intensity on amplitude','Amplitude is multiplied by $1/\\sqrt{2}$ because amplitude is proportional to the square root of intensity.')]
}
for n,rows in qa.items():
 for j,(cmd,topic,ans) in enumerate(rows,1):
  pack['items'].append(dict(id=f'{sub}-i{n}{j}',kcs=[k(n)],kind='short',difficulty=4 if j==6 else (1 if j<3 else 2),command_word=cmd,source={'type':'generated'},stem=f'{cmd} {topic}.',marks=1,rubric=[{'point':ans,'keywords':[[w] for w in ans.replace('$','').replace('\\','').split()[:2]]}],explanation=ans,hints=['Recall the relevant wave quantity.','Link the definition to the physical observation.','Write the defining relationship or observation first.']))
for n,front,back in [(1,'What is wave motion?','Propagation of a disturbance that transfers energy while particles vibrate about equilibrium.'),(2,'Define displacement, amplitude, period, frequency and wavelength.','Displacement: position from equilibrium with direction. Amplitude: maximum displacement from equilibrium. Period: time for one complete oscillation. Frequency: oscillations per unit time. Wavelength: distance between successive points in phase.'),(2,'What are phase difference and wave speed?','Phase difference: angular separation of oscillations. Wave speed: distance travelled by a wavefront per unit time.')]: pack['flashcards'].append(dict(id=f'fc{len(pack["flashcards"])+1}',kc=k(n),front=front,back=back))
for n,problem,formula,answer,unit,faded,fanswer in [(3,'A CRO trace spans 4 divisions per cycle at 0.50 ms per division. Determine frequency.','T = 4 × 0.50 ms = 2.0 ms; f = 1/T',500,'Hz','A cycle spans 5 divisions at 0.40 ms per division. Determine frequency.',500),(4,'Show that the speed of a wave of wavelength 0.60 m and period 0.20 s is 3.0 m s^-1.','v = λ/T = fλ',3,'m s^-1','A wave has wavelength 0.80 m and period 0.20 s. Determine speed.',4),(5,'A wave has frequency 25 Hz and wavelength 0.40 m. Calculate speed.','v = fλ = 25 × 0.40',10,'m s^-1','A wave has frequency 30 Hz and wavelength 0.50 m. Calculate speed.',15),(7,'A wave delivers 12 W through 3.0 m^2. Calculate its intensity.','I = P/A = 12/3.0',4,'W m^-2','A wave delivers 20 W through 4.0 m^2. Calculate intensity.',5)]:
 assert answer==({'3':4} if False else answer)
 pack['worked'].append(dict(id=f'we{n}',kc=k(n),problem=problem,steps=[{'do':formula,'why':'Apply the defining relation to the measured quantities.'},{'do':f'Answer: {answer} {unit}.','why':'Include the appropriate unit.','check':{'kind':'numeric','answer':{'value':answer,'unit':unit,'sf_ok':[2,3]}}}],faded={'id':f'we{n}f','problem':faded,'answer':{'value':fanswer,'unit':unit,'sf_ok':[2,3]},'blank_from':1}))
# Exact arithmetic for the displayed worked values.
assert Fraction(1,4)*Fraction(1000,1)/Fraction(1,2)==500
assert Fraction(60,100)/Fraction(20,100)==3
assert 25*Fraction(40,100)==10
assert Fraction(12,3)==4
out=R/'build/out/packs/9702/9702-7.1.json'; out.parent.mkdir(parents=True,exist_ok=True); out.write_text(json.dumps(pack,ensure_ascii=False,indent=1))
